[{"order":1,"type":"heading","text":"Embedded Objects and Element Collections in Hibernate"},{"order":2,"type":"subheading","text":"Introduction"},{"order":3,"type":"paragraph","text":"In relational database design, we often need to model value types that do not have their own persistent identity. In Hibernate, this is elegantly handled using @Embeddable and @ElementCollection annotations. This tutorial covers how to map value types and collections of value types effectively."},{"order":4,"type":"subheading","text":"Using @Embeddable for Value Types"},{"order":5,"type":"paragraph","text":"An embedded object allows you to group multiple attributes into a reusable class. The properties of the embedded object are stored in the same table as the owning entity. Let us look at an example of an Address value type."},{"order":6,"type":"code","text":"@Embeddable
public class Address {
    private String street;
    private String city;
    private String zipCode;

    // Getters, setters, and constructors
}"},{"order":7,"type":"subheading","text":"Integrating with the Entity"},{"order":8,"type":"paragraph","text":"To use the @Embeddable class inside an entity, annotate the field in the entity class with @Embedded. You can also override column names using @AttributeOverrides if necessary."},{"order":9,"type":"code","text":"@Entity
@Table(name = "users")
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    private String username;

    @Embedded
    @AttributeOverrides({
        @AttributeOverride(name = "street", column = @Column(name = "home_street")),
        @AttributeOverride(name = "city", column = @Column(name = "home_city"))
    })
    private Address homeAddress;
}"},{"order":10,"type":"subheading","text":"Working with Element Collections"},{"order":11,"type":"paragraph","text":"When an entity needs to store a collection of basic types (like Strings) or a collection of embeddable objects, we use the @ElementCollection annotation. Hibernate will map these collections to a separate secondary table."},{"order":12,"type":"code","text":"@Entity
@Table(name = "users")
public class User {
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @ElementCollection
    @CollectionTable(name = "user_phone_numbers", joinColumns = @JoinColumn(name = "user_id"))
    @Column(name = "phone_number")
    private Set<String> phoneNumbers = new HashSet<>();

    @ElementCollection
    @CollectionTable(name = "user_addresses", joinColumns = @JoinColumn(name = "user_id"))
    private List<Address> alternateAddresses = new ArrayList<>();
}"},{"order":13,"type":"subheading","text":"Best Practices and Performance"},{"order":14,"type":"bullet_point","text":"Always implement equals() and hashCode() using business keys when dealing with elements inside a Set."},{"order":15,"type":"bullet_point","text":"Be cautious with List collections containing @Embeddable types, as Hibernate deletes and re-inserts all collection elements on updates unless proper ordering is configured."},{"order":16,"type":"bullet_point","text":"Use appropriate fetch types. Element collections are lazy-loaded by default, which is recommended for performance."}]
